// FUNCTION: BFME2 0x007173E0 size=116 name=??0Quaternion@@QAE@ABVVector3@@M@Z evidence=N:ledger tier=B hypothesis:name:Z
Quaternion::Quaternion(const Vector3 &axis, float angle)
{
	float s = WWMath::Sin(angle / 2);
	float c = WWMath::Cos(angle / 2);
	X = s * axis.X;
	Y = s * axis.Y;
	Z = s * axis.Z;
	W = c;
}

// FUNCTION: BFME2 0x00717460 size=119 name=?Normalize@Quaternion@@QAEXXZ evidence=N:ledger tier=B hypothesis:Z
void Quaternion::Normalize(void)
{
	float len2 = X * X + Y * Y + Z * Z + W * W;
	if (0.0f != len2) {
		float inv_len = WWMath::Inv_Sqrt(len2);
		X *= inv_len;
		Y *= inv_len;
		Z *= inv_len;
		W *= inv_len;
	}
}

// FUNCTION: BFME2 0x007174E0 size=99 name=?Make_Closest@Quaternion@@QAEAAV1@ABV1@@Z evidence=N:ledger tier=B hypothesis:Z
Quaternion &Quaternion::Make_Closest(const Quaternion &target)
{
	// Of q and -q (the same rotation), keep the one nearer to target.
	float dot = target.X * X + target.Y * Y + target.Z * Z + target.W * W;
	if (dot < 0.0) {
		X = -X;
		Y = -Y;
		Z = -Z;
		W = -W;
	}
	return *this;
}

// FUNCTION: BFME2 0x00717550 size=377 name=?BFME2_Nlerp@@YAXAAVQuaternion@@ABV1@1M@Z evidence=N:ledger tier=B hypothesis:Z
void BFME2_Nlerp(Quaternion &res, const Quaternion &quaternion, const Quaternion &q, float alpha)
{
	float dot = quaternion.X * q.X + quaternion.Z * q.Z + quaternion.Y * q.Y + quaternion.W * q.W;
	float beta = 1.0f - alpha;
	if (dot < 0.0f) {
		res.X = beta * quaternion.X - alpha * q.X;
		res.Y = beta * quaternion.Y - alpha * q.Y;
		res.Z = beta * quaternion.Z - alpha * q.Z;
		res.W = beta * quaternion.W - alpha * q.W;
	} else {
		res.X = beta * quaternion.X + alpha * q.X;
		res.Y = beta * quaternion.Y + alpha * q.Y;
		res.Z = beta * quaternion.Z + alpha * q.Z;
		res.W = beta * quaternion.W + alpha * q.W;
	}
	float length = res.X * res.X + res.Y * res.Y + res.Z * res.Z + res.W * res.W;
	if (0.0f != length) {
		float scale = WWMath::Inv_Sqrt(length);
		res.X *= scale;
		res.Y *= scale;
		res.Z *= scale;
		res.W *= scale;
	}
}

// FUNCTION: BFME2 0x007176D0 size=372 name=?Slerp@@YAXAAVQuaternion@@ABV1@1M@Z evidence=N:ledger tier=B hypothesis:Z
void Slerp(Quaternion &res, const Quaternion &p, const Quaternion &q, float alpha)
{
	float beta;		// complementary interploation parameter
	float theta;		// angle between p and q
	float cos_t;		// sine, cosine of theta
	float oo_sin_t;
	int qflip;		// use flip of q?

	// cos theta = dot product of p and q
	cos_t = p.X * q.X + p.Y * q.Y + p.Z * q.Z + p.W * q.W;

	// if q is on opposite hemisphere from A, use -B instead
	if (cos_t < 0.0f) {
		cos_t = -cos_t;
		qflip = true;
	} else {
		qflip = false;
	}

	if (1.0f - cos_t < WWMATH_EPSILON * WWMATH_EPSILON) {

		// if q is very close to p, just linearly interpolate
		// between the two.
		beta = 1.0f - alpha;

	} else {

		// normal slerp!
		theta = WWMath::Acos(cos_t);
		float sin_t = WWMath::Sin(theta);
		oo_sin_t = 1.0f / sin_t;
		beta = WWMath::Sin(theta - alpha * theta) * oo_sin_t;
		alpha = WWMath::Sin(alpha * theta) * oo_sin_t;
	}

	if (qflip) {
		alpha = -alpha;
	}

	res.X = beta * p.X + alpha * q.X;
	res.Y = beta * p.Y + alpha * q.Y;
	res.Z = beta * p.Z + alpha * q.Z;
	res.W = beta * p.W + alpha * q.W;
}

// FUNCTION: BFME2 0x00717850 size=179 name=?Slerp_Setup@@YAXABVQuaternion@@0PAUSlerpInfoStruct@@@Z evidence=N:ledger tier=B hypothesis:Z
void Slerp_Setup(const Quaternion &p, const Quaternion &q, SlerpInfoStruct *slerpinfo)
{
	float cos_t;

	assert(slerpinfo != NULL);

	// cos theta = dot product of p and q
	cos_t = p.X * q.X + p.Y * q.Y + p.Z * q.Z + p.W * q.W;

	// if q is on opposite hemisphere from A, use -B instead
	if (cos_t < 0.0f) {
		cos_t = -cos_t;
		slerpinfo->Flip = true;
	} else {
		slerpinfo->Flip = false;
	}

	if (1.0f - cos_t < SLERP_EPSILON) {

		slerpinfo->Linear = true;
		slerpinfo->Theta = 0.0f;
		slerpinfo->SinT = 0.0f;

	} else {

		slerpinfo->Linear = false;
		slerpinfo->Theta = WWMath::Acos(cos_t);
		slerpinfo->SinT = WWMath::Sin(slerpinfo->Theta);

	}
}

// FUNCTION: BFME2 0x00717910 size=294 name=?Cached_Slerp@@YA?AVQuaternion@@ABV1@0MPAUSlerpInfoStruct@@@Z evidence=N:ledger tier=B hypothesis:Z
Quaternion Cached_Slerp(const Quaternion &p, const Quaternion &q, float alpha, SlerpInfoStruct *slerpinfo)
{
	float beta;		// complementary interploation parameter
	float oo_sin_t;

	if (slerpinfo->Linear) {

		// if q is very close to p, just linearly interpolate
		// between the two.
		beta = 1.0f - alpha;

	} else {

		// normal slerp!
		oo_sin_t = 1.0f / slerpinfo->Theta;
		beta = WWMath::Sin(slerpinfo->Theta - alpha * slerpinfo->Theta) * oo_sin_t;
		alpha = WWMath::Sin(alpha * slerpinfo->Theta) * oo_sin_t;
	}

	if (slerpinfo->Flip) {
		alpha = -alpha;
	}

	Quaternion res;
	res.X = beta * p.X + alpha * q.X;
	res.Y = beta * p.Y + alpha * q.Y;
	res.Z = beta * p.Z + alpha * q.Z;
	res.W = beta * p.W + alpha * q.W;

	return res;
}

